+import { readFileSync, writeFileSync } from "fs";
+import { homedir } from "os";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const STORE_PATH = join(homedir(), ".cache", "session-store.json");
+
+const loadStore = (): Map<string, Entry> => {
+  try {
+    const data = readFileSync(STORE_PATH, "utf-8");
+    const obj = JSON.parse(data);
+    return new Map(Object.entries(obj) as [string, Entry][]);
+  } catch {
+    return new Map();
+  }
+};
+
+const saveStore = (store: Map<string, Entry>): void => {
+  const obj = Object.fromEntries(store);
+  writeFileSync(STORE_PATH, JSON.stringify(obj), "utf-8");
+};
+
+let store = loadStore();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore(store);
 };

